package main

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"time"
)

type Config struct {
	SelfPath        string
	ConfigDir       string
	DataDir         string
	CacheDir        string
	BashPath        string
	DisableStdin    bool
	LoadDotenv      bool
	StrictEnv       bool
	HideEnvDiff     bool
	WarnTimeout     time.Duration
	LogFormat       string
	LogFilter       *regexp.Regexp
	WhitelistPrefix []string
	WhitelistExact  []string
}

type RC struct {
	Path     string
	Dir      string
	Base     string
	IsDotenv bool
}

type RCState int

const (
	RCAllowed RCState = iota
	RCBlocked
	RCDenied
)

func loadConfig() (Config, error) {
	selfPath, err := os.Executable()
	if err != nil {
		return Config{}, err
	}
	if resolved, err := filepath.EvalSymlinks(selfPath); err == nil {
		selfPath = resolved
	}

	home := os.Getenv("HOME")
	configHome := os.Getenv("XDG_CONFIG_HOME")
	if configHome == "" {
		configHome = filepath.Join(home, ".config")
	}
	dataHome := os.Getenv("XDG_DATA_HOME")
	if dataHome == "" {
		dataHome = filepath.Join(home, ".local", "share")
	}
	cacheHome := os.Getenv("XDG_CACHE_HOME")
	if cacheHome == "" {
		cacheHome = filepath.Join(home, ".cache")
	}

	cfg := Config{
		SelfPath:    selfPath,
		ConfigDir:   filepath.Join(configHome, "direnv"),
		DataDir:     filepath.Join(dataHome, "direnv"),
		CacheDir:    filepath.Join(cacheHome, "direnv"),
		BashPath:    "/usr/bin/bash",
		WarnTimeout: 5 * time.Second,
	}

	if err := loadTomlConfig(&cfg); err != nil {
		return Config{}, err
	}
	if env := os.Getenv("DIRENV_WARN_TIMEOUT"); env != "" {
		if d, err := time.ParseDuration(env); err == nil {
			cfg.WarnTimeout = d
		}
	}
	return cfg, nil
}

func loadTomlConfig(cfg *Config) error {
	path := filepath.Join(cfg.ConfigDir, "direnv.toml")
	file, err := os.Open(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	defer file.Close()

	section := ""
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = strings.TrimSpace(line[:idx])
		}
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[") && strings.HasSuffix(line, "]") {
			section = strings.TrimSpace(line[1 : len(line)-1])
			continue
		}
		key, val, ok := strings.Cut(line, "=")
		if !ok {
			continue
		}
		key = strings.TrimSpace(key)
		val = strings.TrimSpace(val)
		switch section {
		case "global":
			switch key {
			case "bash_path":
				if s, err := parseTomlString(val); err == nil && s != "" {
					cfg.BashPath = s
				}
			case "disable_stdin":
				cfg.DisableStdin = parseTomlBool(val)
			case "load_dotenv":
				cfg.LoadDotenv = parseTomlBool(val)
			case "strict_env":
				cfg.StrictEnv = parseTomlBool(val)
			case "hide_env_diff":
				cfg.HideEnvDiff = parseTomlBool(val)
			case "warn_timeout":
				if s, err := parseTomlString(val); err == nil {
					if d, err := time.ParseDuration(s); err == nil {
						cfg.WarnTimeout = d
					}
				}
			case "log_format":
				if s, err := parseTomlString(val); err == nil {
					cfg.LogFormat = s
				}
			case "log_filter":
				if s, err := parseTomlString(val); err == nil && s != "" {
					if re, err := regexp.Compile(s); err == nil {
						cfg.LogFilter = re
					}
				}
			}
		case "whitelist":
			switch key {
			case "prefix":
				if list, err := parseTomlStringArray(val); err == nil {
					cfg.WhitelistPrefix = list
				}
			case "exact":
				if list, err := parseTomlStringArray(val); err == nil {
					cfg.WhitelistExact = list
				}
			}
		}
	}
	return scanner.Err()
}

func parseTomlString(raw string) (string, error) {
	raw = strings.TrimSpace(raw)
	return strconv.Unquote(raw)
}

func parseTomlBool(raw string) bool {
	raw = strings.TrimSpace(raw)
	return raw == "true"
}

func parseTomlStringArray(raw string) ([]string, error) {
	var out []string
	if err := json.Unmarshal([]byte(raw), &out); err != nil {
		return nil, err
	}
	return out, nil
}

func findRCFrom(start string, cfg Config) (*RC, error) {
	dir, err := filepath.Abs(start)
	if err != nil {
		return nil, err
	}
	info, err := os.Stat(dir)
	if err != nil {
		return nil, err
	}
	if !info.IsDir() {
		dir = filepath.Dir(dir)
	}

	for {
		envrc := filepath.Join(dir, ".envrc")
		if info, err := os.Stat(envrc); err == nil && !info.IsDir() {
			return &RC{Path: envrc, Dir: dir, Base: ".envrc"}, nil
		}
		if cfg.LoadDotenv {
			dotenv := filepath.Join(dir, ".env")
			if info, err := os.Stat(dotenv); err == nil && !info.IsDir() {
				return &RC{Path: dotenv, Dir: dir, Base: ".env", IsDotenv: true}, nil
			}
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return nil, nil
		}
		dir = parent
	}
}

func resolveRCForArg(arg string, cfg Config) (*RC, error) {
	if arg == "" {
		rc, err := findRCFrom(".", cfg)
		if err != nil {
			return nil, err
		}
		if rc == nil {
			return nil, errors.New(".envrc file not found")
		}
		return rc, nil
	}

	path, err := filepath.Abs(arg)
	if err != nil {
		return nil, err
	}
	info, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}
	if info.IsDir() {
		rc, err := findRCFrom(path, cfg)
		if err != nil {
			return nil, err
		}
		if rc == nil {
			return nil, errors.New(".envrc file not found")
		}
		return rc, nil
	}
	base := filepath.Base(path)
	switch base {
	case ".envrc":
		return &RC{Path: path, Dir: filepath.Dir(path), Base: base}, nil
	case ".env":
		return &RC{Path: path, Dir: filepath.Dir(path), Base: base, IsDotenv: true}, nil
	default:
		return nil, fmt.Errorf("lstat %s: not a directory", path)
	}
}

func resolveEditTarget(arg string, cfg Config) (*RC, bool, error) {
	if arg == "" {
		rc, err := findRCFrom(".", cfg)
		if err != nil {
			return nil, false, err
		}
		if rc == nil {
			return nil, false, errors.New(".envrc or .env not found. Use `direnv edit .` to create a new .envrc in the current directory")
		}
		return rc, false, nil
	}

	path, err := filepath.Abs(arg)
	if err != nil {
		return nil, false, err
	}
	info, err := os.Stat(path)
	if err == nil && info.IsDir() {
		rc, err := findRCFrom(path, cfg)
		if err != nil {
			return nil, false, err
		}
		if rc != nil {
			return rc, false, nil
		}
		return &RC{Path: filepath.Join(path, ".envrc"), Dir: path, Base: ".envrc"}, true, nil
	}
	if err == nil && !info.IsDir() {
		base := filepath.Base(path)
		switch base {
		case ".envrc":
			return &RC{Path: path, Dir: filepath.Dir(path), Base: base}, false, nil
		case ".env":
			return &RC{Path: path, Dir: filepath.Dir(path), Base: base, IsDotenv: true}, false, nil
		}
	}
	if errors.Is(err, os.ErrNotExist) {
		base := filepath.Base(path)
		switch base {
		case ".envrc":
			return &RC{Path: path, Dir: filepath.Dir(path), Base: base}, true, nil
		case ".env":
			return &RC{Path: path, Dir: filepath.Dir(path), Base: base, IsDotenv: true}, true, nil
		}
	}
	return nil, false, err
}

func allowPathFor(rcPath string, content []byte, cfg Config) string {
	sum := sha256.Sum256(append([]byte(rcPath+"\n"), content...))
	return filepath.Join(cfg.DataDir, "allow", hex.EncodeToString(sum[:]))
}

func denyPathFor(rcPath string, cfg Config) string {
	sum := sha256.Sum256([]byte(rcPath + "\n"))
	return filepath.Join(cfg.DataDir, "deny", hex.EncodeToString(sum[:]))
}

func requiredDirFor(envrcPath string, cfg Config) string {
	sum := sha256.Sum256([]byte(envrcPath + "\n"))
	return filepath.Join(cfg.DataDir, "allowed-required", hex.EncodeToString(sum[:]))
}

func requiredPathFor(envrcPath, relPath string, content []byte, cfg Config) string {
	sum := sha256.Sum256(append([]byte(relPath+"\n"), content...))
	return filepath.Join(requiredDirFor(envrcPath, cfg), hex.EncodeToString(sum[:]))
}

func rcState(cfg Config, rc *RC) (RCState, string, string, []Watch, error) {
	content, err := os.ReadFile(rc.Path)
	if err != nil {
		return RCBlocked, "", "", nil, err
	}
	allowPath := allowPathFor(rc.Path, content, cfg)
	denyPath := denyPathFor(rc.Path, cfg)
	watches := []Watch{
		newWatch(rc.Path),
		newWatch(allowPath),
		newWatch(denyPath),
	}
	if whitelisted(cfg, rc.Path) {
		return RCAllowed, allowPath, denyPath, watches, nil
	}
	if exists(denyPath) {
		return RCDenied, allowPath, denyPath, watches, nil
	}
	if exists(allowPath) {
		return RCAllowed, allowPath, denyPath, watches, nil
	}
	return RCBlocked, allowPath, denyPath, watches, nil
}

func whitelisted(cfg Config, path string) bool {
	path = filepath.Clean(path)
	for _, prefix := range cfg.WhitelistPrefix {
		expanded := filepath.Clean(expandUser(prefix))
		if strings.HasPrefix(path, expanded) {
			return true
		}
	}
	for _, exact := range cfg.WhitelistExact {
		expanded := filepath.Clean(expandUser(exact))
		info, err := os.Stat(expanded)
		if err == nil && info.IsDir() {
			expanded = filepath.Join(expanded, ".envrc")
		}
		if path == expanded {
			return true
		}
	}
	return false
}

func expandUser(path string) string {
	if strings.HasPrefix(path, "~/") || path == "~" {
		return filepath.Join(os.Getenv("HOME"), strings.TrimPrefix(path, "~/"))
	}
	return path
}

func exists(path string) bool {
	_, err := os.Stat(path)
	return err == nil
}

