func mergeWatches(existing []Watch, incoming []Watch) []Watch {
	byPath := make(map[string]Watch, len(existing)+len(incoming))
	for _, watch := range existing {
		byPath[watch.Path] = watch
	}
	for _, watch := range incoming {
		byPath[watch.Path] = watch
	}
	keys := make([]string, 0, len(byPath))
	for key := range byPath {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	out := make([]Watch, 0, len(keys))
	for _, key := range keys {
		out = append(out, byPath[key])
	}
	return out
