func watchesCurrent(watches []Watch) bool {
	for _, watch := range watches {
		info, err := os.Stat(watch.Path)
		if watch.Exists {
			if err != nil {
				return false
			}
			if info.ModTime().Unix() != watch.ModTime {
				return false
			}
			continue
		}
		if err == nil {
			return false
		}
	}
	return true
}

func isSpecialKey(key string) bool {
	return strings.HasPrefix(key, "DIRENV_")
}

func diffSummary(base, target map[string]string) string {
	diff := diffFromBase(base, target)
	var added, removed, changed []string
	keys := make(map[string]struct{})
	for key := range diff.N {
		keys[key] = struct{}{}
	}
	for key := range diff.P {
		keys[key] = struct{}{}
	}
	for key := range keys {
		if isSpecialKey(key) || key == "DIRENV_IN_ENVRC" {
			continue
		}
		_, inN := diff.N[key]
		_, inP := diff.P[key]
		switch {
		case inN && !inP:
			added = append(added, key)
		case !inN && inP:
			removed = append(removed, key)
		case inN && inP:
			changed = append(changed, key)
		}
	}
	sort.Strings(added)
	sort.Strings(removed)
	sort.Strings(changed)
	parts := make([]string, 0, len(added)+len(removed)+len(changed))
	for _, key := range added {
		parts = append(parts, "+"+key)
	}
	for _, key := range removed {
		parts = append(parts, "-"+key)
	}
	for _, key := range changed {
		parts = append(parts, "~"+key)
	}
	return strings.Join(parts, " ")
}

func relativeDisplayPath(path string) string {
	cwd, err := os.Getwd()
	if err != nil {
		return path
	}
	if rel, err := filepath.Rel(cwd, path); err == nil && rel != "" {
		return rel
	}
	return path
}

func userRelPath(path string) string {
	home := os.Getenv("HOME")
	if home != "" && strings.HasPrefix(path, home) {
		return "~" + strings.TrimPrefix(path, home)
	}
	return path
}

func isTTY(file *os.File) bool {
	info, err := file.Stat()
	if err != nil {
		return false
	}
	return (info.Mode() & os.ModeCharDevice) != 0
}

func parseVersion(raw string) ([3]int, error) {
	var out [3]int
	raw = strings.TrimPrefix(strings.TrimSpace(raw), "v")
	parts := strings.Split(raw, ".")
	if len(parts) != 3 {
		return out, fmt.Errorf("v%s is not a valid semver version", raw)
	}
	for i, part := range parts {
		n, err := strconv.Atoi(part)
		if err != nil {
			return out, fmt.Errorf("v%s is not a valid semver version", raw)
		}
		out[i] = n
	}
	return out, nil
}

