package main

import (
	"crypto/sha256"
	"encoding/base64"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

func sriSHA256(data []byte) string {
	sum := sha256.Sum256(data)
	return "sha256-" + base64.StdEncoding.EncodeToString(sum[:])
}

func sriToHex(integrity string) ([]byte, error) {
	if !strings.HasPrefix(integrity, "sha256-") {
		return nil, fmt.Errorf("sri: not a hash %s", integrity)
	}
	raw, err := base64.StdEncoding.DecodeString(strings.TrimPrefix(integrity, "sha256-"))
	if err != nil {
		return nil, fmt.Errorf("sri: not a hash %s", integrity)
	}
	return raw, nil
}

func fetchURL(cfg Config, url, integrity string) error {
	body, err := httpGetBytes(url)
	if err != nil {
		return err
	}
	actual := sriSHA256(body)
	sum := sha256.Sum256(body)
	cachePath := filepath.Join(cfg.CacheDir, "cas", hex.EncodeToString(sum[:]))

	if integrity == "" {
		if err := os.MkdirAll(filepath.Dir(cachePath), 0o755); err != nil {
			return err
		}
		if _, err := os.Stat(cachePath); err != nil {
			if err := os.WriteFile(cachePath, body, 0o500); err != nil {
				return err
			}
			if err := os.Chmod(cachePath, 0o500); err != nil {
				return err
			}
		}
		if isTTY(os.Stdout) {
			fmt.Fprintf(os.Stdout, "Found hash: %s\n\n", actual)
			fmt.Fprintln(os.Stdout, "Invoke fetchurl again with the hash as an argument to get the disk location:")
			fmt.Fprintln(os.Stdout)
			fmt.Fprintf(os.Stdout, "  direnv fetchurl %q %q\n", url, actual)
			fmt.Fprintf(os.Stdout, "  #=> %s\n", cachePath)
		} else {
			fmt.Fprintln(os.Stdout, actual)
		}
		return nil
	}

	expected, err := sriToHex(integrity)
	if err != nil {
		return err
	}
	if !strings.EqualFold(hex.EncodeToString(expected), hex.EncodeToString(sum[:])) {
		return fmt.Errorf("hash mismatch. Expected %q but got %q", integrity, actual)
	}
	if err := os.MkdirAll(filepath.Dir(cachePath), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(cachePath, body, 0o500); err != nil {
		return err
	}
	if err := os.Chmod(cachePath, 0o500); err != nil {
		return err
	}
	fmt.Fprintln(os.Stdout, cachePath)
	return nil
}

func httpGetBytes(url string) ([]byte, error) {
	resp, err := http.Get(url) //nolint:gosec
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("expected status code 200 but got %d", resp.StatusCode)
	}
	return io.ReadAll(resp.Body)
}

