+	if err != nil {
+		return err
+	}
+	if current[0] < desired[0] || (current[0] == desired[0] && current[1] < desired[1]) || (current[0] == desired[0] && current[1] == desired[1] && current[2] < desired[2]) {
+		return fmt.Errorf("current version v%s is older than the desired version v%s", direnvVersion, strings.TrimPrefix(args[0], "v"))
+	}
+	return nil
+}
+
+func cmdAllow(cfg Config, arg string) error {
+	rc, err := resolveRCForArg(arg, cfg)
+	if err != nil {
+		return err
+	}
+	if err := allowRC(cfg, rc); err != nil {
+		return err
+	}
+	if reqs := strings.Fields(os.Getenv("DIRENV_REQUIRED")); len(reqs) > 0 {
+		for _, rel := range reqs {
+			if err := approveRequiredPath(cfg, rc.Path, rc.Dir, rel); err != nil {
+				return err
+			}
+			fmt.Fprintf(os.Stdout, "direnv: allowing %s\n", rel)
+		}
+	}
+	return nil
+}
+
+func allowRC(cfg Config, rc *RC) error {
+	content, err := os.ReadFile(rc.Path)
+	if err != nil {
+		return err
+	}
+	allowPath := allowPathFor(rc.Path, content, cfg)
+	if err := os.MkdirAll(filepath.Dir(allowPath), 0o755); err != nil {
+		return err
+	}
+	if err := os.WriteFile(allowPath, []byte(rc.Path+"\n"), 0o644); err != nil {
+		return err
+	}
+	_ = os.Remove(denyPathFor(rc.Path, cfg))
+	return nil
+}
+
+func cmdBlock(cfg Config, arg string) error {
+	rc, err := resolveRCForArg(arg, cfg)
+	if err != nil {
+		return err
+	}
+	denyPath := denyPathFor(rc.Path, cfg)
+	if err := os.MkdirAll(filepath.Dir(denyPath), 0o755); err != nil {
+		return err
+	}
+	if err := os.WriteFile(denyPath, []byte(rc.Path+"\n"), 0o644); err != nil {
+		return err
+	}
+	allowDir := filepath.Join(cfg.DataDir, "allow")
+	entries, _ := os.ReadDir(allowDir)
+	for _, entry := range entries {
+		path := filepath.Join(allowDir, entry.Name())
+		data, err := os.ReadFile(path)
+		if err == nil && string(data) == rc.Path+"\n" {
+			_ = os.Remove(path)
+		}
+	}
+	return nil
+}
+
+func cmdEdit(cfg Config, arg string) error {
+	rc, _, err := resolveEditTarget(arg, cfg)
+	if err != nil {
+		return err
+	}
+	before, _ := os.ReadFile(rc.Path)
+	editor := os.Getenv("EDITOR")
+	if editor == "" {
+		editor = "vi"
+	}
+	cmd := exec.Command("sh", "-c", editor+" "+singleQuote(rc.Path))
+	cmd.Stdin = os.Stdin
+	cmd.Stdout = os.Stdout
+	cmd.Stderr = os.Stderr
+	if err := cmd.Run(); err != nil {
+		return err
+	}
+	after, err := os.ReadFile(rc.Path)
+	if err != nil {
+		if errors.Is(err, os.ErrNotExist) {
+			return nil
+		}
+		return err
+	}
+	if string(before) != string(after) {
+		return allowRC(cfg, rc)
+	}
+	return nil
+}
+
+func cmdExec(cfg Config, args []string) error {
+	if len(args) < 2 {
+		return errors.New("missing DIR and COMMAND arguments")
+	}
+	base := baseEnvFromCurrent()
+	rc, err := findRCFrom(args[0], cfg)
+	if err != nil && !errors.Is(err, os.ErrNotExist) {
+		return err
+	}
+	if rc == nil {
+		return runChild(args[1:], base)
+	}
+
+	state, allowPath, _, baseWatches, err := rcState(cfg, rc)
+	if err != nil {
+		return err
+	}
+	if state == RCBlocked {
+		return fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", rc.Path)
+	}
+	if state == RCDenied {
+		_ = allowPath
+		return runChild(args[1:], base)
+	}
+
+	statusLog(cfg, "loading "+userRelPath(rc.Path))
+	evaluated, err := evaluateRC(cfg, rc, base)
+	if len(evaluated.Stderr) > 0 {
+		_, _ = os.Stderr.Write(evaluated.Stderr)
+	}
+	target := sanitizeEvaluatedEnv(base, evaluated.Env, true)
+	watches := mergedWatchesFromEnv(target["DIRENV_WATCHES"], baseWatches)
+	watchesEnc, err := encodeObject(watches)
+	if err != nil {
+		return err
+	}
+	target["DIRENV_DIR"] = "-" + rc.Dir
+	target["DIRENV_FILE"] = rc.Path
+	target["DIRENV_WATCHES"] = watchesEnc
+	delete(target, "DIRENV_DIFF")
+	diff := diffFromBase(base, target)
+	diffEnc, err := encodeObject(diff)
+	if err != nil {
+		return err
+	}
+	target["DIRENV_DIFF"] = diffEnc
+	if err != nil {
+		return err
+	}
+	return runChild(args[1:], target)
+}
+
+func runChild(args []string, env map[string]string) error {
+	cmd := exec.Command(args[0], args[1:]...)
+	cmd.Env = envListFromMap(env)
+	cmd.Stdin = os.Stdin
+	cmd.Stdout = os.Stdout
+	cmd.Stderr = os.Stderr
+	if err := cmd.Run(); err != nil {
+		var exitErr *exec.ExitError
+		if errors.As(err, &exitErr) {
+			os.Exit(exitErr.ExitCode())
+		}
+		return err
+	}
+	return nil
+}
