+func cmdExport(cfg Config, args []string) error {
+	if len(args) == 0 {
+		return fmt.Errorf("unknown target shell ''")
+	}
+	shell := args[0]
+	if !supportsExportShell(shell) {
+		return fmt.Errorf("unknown target shell '%s'", shell)
+	}
+
+	current := envMap()
+	base := baseEnvFromMap(current)
+	loadedPath := current["DIRENV_FILE"]
+	currentWatches, _ := decodeWatches(current["DIRENV_WATCHES"])
+	foundRC, err := findRCFrom(".", cfg)
+	if err != nil {
+		return err
+	}
+
+	if foundRC == nil {
+		if loadedPath != "" {
+			statusLog(cfg, "unloading")
+		}
+		return renderToStdout(shell, changesBetween(current, base))
+	}
+
+	if loadedPath == foundRC.Path && watchesCurrent(currentWatches) {
+		return nil
+	}
+
+	state, _, _, baseWatches, err := rcState(cfg, foundRC)
+	if err != nil {
+		return err
+	}
+	switch state {
+	case RCBlocked, RCDenied:
+		target := cloneEnv(base)
+		watchesEnc, err := encodeObject(baseWatches)
+		if err != nil {
+			return err
+		}
+		target["DIRENV_DIR"] = "-" + foundRC.Dir
+		target["DIRENV_FILE"] = foundRC.Path
+		target["DIRENV_WATCHES"] = watchesEnc
+		diff := diffFromBase(base, target)
+		diffEnc, err := encodeObject(diff)
+		if err != nil {
+			return err
+		}
+		target["DIRENV_DIFF"] = diffEnc
+		if err := renderToStdout(shell, changesBetween(current, target)); err != nil {
+			return err
+		}
+		if state == RCBlocked {
+			return fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", foundRC.Path)
+		}
+		return nil
+	case RCAllowed:
+		statusLog(cfg, "loading "+userRelPath(foundRC.Path))
+		evaluated, err := evaluateRC(cfg, foundRC, base)
+		if len(evaluated.Stderr) > 0 {
+			_, _ = os.Stderr.Write(evaluated.Stderr)
+		}
+		target := sanitizeEvaluatedEnv(base, evaluated.Env, false)
+		watches := mergedWatchesFromEnv(target["DIRENV_WATCHES"], baseWatches)
+		watchesEnc, err := encodeObject(watches)
+		if err != nil {
+			return err
+		}
+		target["DIRENV_DIR"] = "-" + foundRC.Dir
+		target["DIRENV_FILE"] = foundRC.Path
+		target["DIRENV_WATCHES"] = watchesEnc
+		delete(target, "DIRENV_DIFF")
+		diff := diffFromBase(base, target)
+		diffEnc, err := encodeObject(diff)
+		if err != nil {
+			return err
+		}
+		target["DIRENV_DIFF"] = diffEnc
+		if summary := diffSummary(base, target); summary != "" && !cfg.HideEnvDiff {
+			statusLog(cfg, "export "+summary)
+		}
+		if err := renderToStdout(shell, changesBetween(current, target)); err != nil {
+			return err
+		}
+		if err != nil {
+			return err
+		}
+		return nil
+	default:
+		return nil
+	}
+}
