+func cmdWatchDir(args []string) error {
+	if len(args) < 2 {
+		return errors.New("invalid arguments")
+	}
+	shell := args[0]
+	if !supportsExportShell(shell) {
+		return fmt.Errorf("unknown target shell '%s'", shell)
+	}
+	root, err := filepath.Abs(args[1])
+	if err != nil {
+		return err
+	}
+	existing, _ := decodeWatches(os.Getenv("DIRENV_WATCHES"))
+	var incoming []Watch
+	err = filepath.Walk(root, func(path string, info os.FileInfo, walkErr error) error {
+		if walkErr != nil {
+			return nil
+		}
+		incoming = append(incoming, newWatch(path))
+		return nil
+	})
+	if err != nil {
+		return err
+	}
+	merged := mergeWatches(existing, incoming)
+	enc, err := encodeObject(merged)
+	if err != nil {
+		return err
+	}
+	return renderToStdout(shell, map[string]*string{"DIRENV_WATCHES": &enc})
+}
