package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
)

const direnvVersion = "2.37.1"

var exportShells = []string{"bash", "elvish", "fish", "gha", "gzenv", "json", "murex", "pwsh", "systemd", "tcsh", "vim", "zsh"}

func main() {
	cfg, err := loadConfig()
	if err != nil {
		fatalErr(err)
	}
	if err := run(cfg, os.Args); err != nil {
		fatalErr(err)
	}
}

func run(cfg Config, argv []string) error {
	args := argv[1:]
	if len(args) == 0 {
		printHelp(false)
		return nil
	}

	switch args[0] {
	case "help", "--help":
		printHelp(len(args) > 1)
		return nil
	case "version", "--version":
		return cmdVersion(args[1:])
	case "allow", "permit", "grant":
		return cmdAllow(cfg, optionalArg(args[1:]))
	case "block", "deny", "disallow", "revoke":
		return cmdBlock(cfg, optionalArg(args[1:]))
	case "edit":
		return cmdEdit(cfg, optionalArg(args[1:]))
	case "exec":
		return cmdExec(cfg, args[1:])
	case "export":
		return cmdExport(cfg, args[1:])
	case "fetchurl":
		return cmdFetchurl(cfg, args[1:])
	case "hook":
		return cmdHook(cfg, args[1:])
	case "prune":
		return cmdPrune(cfg)
	case "reload":
		return cmdReload()
	case "status":
		return cmdStatus(cfg, args[1:])
	case "stdlib":
		_, _ = io.WriteString(os.Stdout, stdlibScript(cfg.SelfPath))
		return nil
	case "log":
		return cmdLog(args[1:])
	case "dump":
		return cmdDump(args[1:])
	case "apply_dump":
		return cmdApplyDump(args[1:])
	case "show_dump":
		return cmdShowDump(args[1:])
	case "watch":
		return cmdWatch(args[1:])
	case "watch-dir":
		return cmdWatchDir(args[1:])
	case "watch-list":
		return cmdWatchList(args[1:])
	case "watch-print":
		return cmdWatchPrint(args[1:])
	case "current":
		return cmdCurrent(args[1:])
	case "check-required":
		return cmdCheckRequired(cfg, args[1:])
	case "dotenv":
		return cmdDotenv(cfg, args[1:])
	default:
		return fmt.Errorf("command %q not found", strings.Join(argv, " "))
	}
}

func optionalArg(args []string) string {
	if len(args) == 0 {
		return ""
	}
	return args[0]
}

func cmdVersion(args []string) error {
	if len(args) == 0 {
		fmt.Fprintln(os.Stdout, direnvVersion)
		return nil
	}
	current, _ := parseVersion(direnvVersion)
	desired, err := parseVersion(args[0])
	if err != nil {
		return err
	}
	if current[0] < desired[0] || (current[0] == desired[0] && current[1] < desired[1]) || (current[0] == desired[0] && current[1] == desired[1] && current[2] < desired[2]) {
		return fmt.Errorf("current version v%s is older than the desired version v%s", direnvVersion, strings.TrimPrefix(args[0], "v"))
	}
	return nil
}

func cmdAllow(cfg Config, arg string) error {
	rc, err := resolveRCForArg(arg, cfg)
	if err != nil {
		return err
	}
	if err := allowRC(cfg, rc); err != nil {
		return err
	}
	if reqs := strings.Fields(os.Getenv("DIRENV_REQUIRED")); len(reqs) > 0 {
		for _, rel := range reqs {
			if err := approveRequiredPath(cfg, rc.Path, rc.Dir, rel); err != nil {
				return err
			}
			fmt.Fprintf(os.Stdout, "direnv: allowing %s\n", rel)
		}
	}
	return nil
}

func allowRC(cfg Config, rc *RC) error {
	content, err := os.ReadFile(rc.Path)
	if err != nil {
		return err
	}
	allowPath := allowPathFor(rc.Path, content, cfg)
	if err := os.MkdirAll(filepath.Dir(allowPath), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(allowPath, []byte(rc.Path+"\n"), 0o644); err != nil {
		return err
	}
	_ = os.Remove(denyPathFor(rc.Path, cfg))
	return nil
}

func cmdBlock(cfg Config, arg string) error {
	rc, err := resolveRCForArg(arg, cfg)
	if err != nil {
		return err
	}
	denyPath := denyPathFor(rc.Path, cfg)
	if err := os.MkdirAll(filepath.Dir(denyPath), 0o755); err != nil {
		return err
	}
	if err := os.WriteFile(denyPath, []byte(rc.Path+"\n"), 0o644); err != nil {
		return err
	}
	allowDir := filepath.Join(cfg.DataDir, "allow")
	entries, _ := os.ReadDir(allowDir)
	for _, entry := range entries {
		path := filepath.Join(allowDir, entry.Name())
		data, err := os.ReadFile(path)
		if err == nil && string(data) == rc.Path+"\n" {
			_ = os.Remove(path)
		}
	}
	return nil
}

func cmdEdit(cfg Config, arg string) error {
	rc, _, err := resolveEditTarget(arg, cfg)
	if err != nil {
		return err
	}
	before, _ := os.ReadFile(rc.Path)
	editor := os.Getenv("EDITOR")
	if editor == "" {
		editor = "vi"
	}
	cmd := exec.Command("sh", "-c", editor+" "+singleQuote(rc.Path))
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return err
	}
	after, err := os.ReadFile(rc.Path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	if string(before) != string(after) {
		return allowRC(cfg, rc)
	}
	return nil
}

func cmdExec(cfg Config, args []string) error {
	if len(args) < 2 {
		return errors.New("missing DIR and COMMAND arguments")
	}
	base := baseEnvFromCurrent()
	rc, err := findRCFrom(args[0], cfg)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	if rc == nil {
		return runChild(args[1:], base)
	}

	state, allowPath, _, baseWatches, err := rcState(cfg, rc)
	if err != nil {
		return err
	}
	if state == RCBlocked {
		return fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", rc.Path)
	}
	if state == RCDenied {
		_ = allowPath
		return runChild(args[1:], base)
	}

	statusLog(cfg, "loading "+userRelPath(rc.Path))
	evaluated, err := evaluateRC(cfg, rc, base)
	if len(evaluated.Stderr) > 0 {
		_, _ = os.Stderr.Write(evaluated.Stderr)
	}
	target := sanitizeEvaluatedEnv(base, evaluated.Env, true)
	watches := mergedWatchesFromEnv(target["DIRENV_WATCHES"], baseWatches)
	watchesEnc, err := encodeObject(watches)
	if err != nil {
		return err
	}
	target["DIRENV_DIR"] = "-" + rc.Dir
	target["DIRENV_FILE"] = rc.Path
	target["DIRENV_WATCHES"] = watchesEnc
	delete(target, "DIRENV_DIFF")
	diff := diffFromBase(base, target)
	diffEnc, err := encodeObject(diff)
	if err != nil {
		return err
	}
	target["DIRENV_DIFF"] = diffEnc
	if err != nil {
		return err
	}
	return runChild(args[1:], target)
}

func runChild(args []string, env map[string]string) error {
	cmd := exec.Command(args[0], args[1:]...)
	cmd.Env = envListFromMap(env)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			os.Exit(exitErr.ExitCode())
		}
		return err
	}
	return nil
}

func cmdExport(cfg Config, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("unknown target shell ''")
	}
	shell := args[0]
	if !supportsExportShell(shell) {
		return fmt.Errorf("unknown target shell '%s'", shell)
	}

	current := envMap()
	base := baseEnvFromMap(current)
	loadedPath := current["DIRENV_FILE"]
	currentWatches, _ := decodeWatches(current["DIRENV_WATCHES"])
	foundRC, err := findRCFrom(".", cfg)
	if err != nil {
		return err
	}

	if foundRC == nil {
		if loadedPath != "" {
			statusLog(cfg, "unloading")
		}
		return renderToStdout(shell, changesBetween(current, base))
	}

	if loadedPath == foundRC.Path && watchesCurrent(currentWatches) {
		return nil
	}

	state, _, _, baseWatches, err := rcState(cfg, foundRC)
	if err != nil {
		return err
	}
	switch state {
	case RCBlocked, RCDenied:
		target := cloneEnv(base)
		watchesEnc, err := encodeObject(baseWatches)
		if err != nil {
			return err
		}
		target["DIRENV_DIR"] = "-" + foundRC.Dir
		target["DIRENV_FILE"] = foundRC.Path
		target["DIRENV_WATCHES"] = watchesEnc
		diff := diffFromBase(base, target)
		diffEnc, err := encodeObject(diff)
		if err != nil {
			return err
		}
		target["DIRENV_DIFF"] = diffEnc
		if err := renderToStdout(shell, changesBetween(current, target)); err != nil {
			return err
		}
		if state == RCBlocked {
			return fmt.Errorf("%s is blocked. Run `direnv allow` to approve its content", foundRC.Path)
		}
		return nil
	case RCAllowed:
		statusLog(cfg, "loading "+userRelPath(foundRC.Path))
		evaluated, err := evaluateRC(cfg, foundRC, base)
		if len(evaluated.Stderr) > 0 {
			_, _ = os.Stderr.Write(evaluated.Stderr)
		}
		target := sanitizeEvaluatedEnv(base, evaluated.Env, false)
		watches := mergedWatchesFromEnv(target["DIRENV_WATCHES"], baseWatches)
		watchesEnc, err := encodeObject(watches)
		if err != nil {
			return err
		}
		target["DIRENV_DIR"] = "-" + foundRC.Dir
		target["DIRENV_FILE"] = foundRC.Path
		target["DIRENV_WATCHES"] = watchesEnc
		delete(target, "DIRENV_DIFF")
		diff := diffFromBase(base, target)
		diffEnc, err := encodeObject(diff)
		if err != nil {
			return err
		}
		target["DIRENV_DIFF"] = diffEnc
		if summary := diffSummary(base, target); summary != "" && !cfg.HideEnvDiff {
			statusLog(cfg, "export "+summary)
		}
		if err := renderToStdout(shell, changesBetween(current, target)); err != nil {
			return err
		}
		if err != nil {
			return err
		}
		return nil
	default:
		return nil
	}
}

