func cmdStatus(cfg Config, args []string) error {
	jsonMode := false
	if len(args) > 0 {
		if len(args) == 1 && args[0] == "--json" {
			jsonMode = true
		} else {
			return errors.New("invalid arguments")
		}
	}

	current := envMap()
	loadedPath := current["DIRENV_FILE"]
	foundRC, _ := findRCFrom(".", cfg)

	type rcJSON struct {
		Allowed int    `json:"allowed"`
		Path    string `json:"path"`
	}
	if jsonMode {
		out := struct {
			Config struct {
				ConfigDir string
				SelfPath  string
			} `json:"config"`
			State struct {
				FoundRC  *rcJSON `json:"foundRC"`
				LoadedRC *rcJSON `json:"loadedRC"`
			} `json:"state"`
		}{}
		out.Config.ConfigDir = cfg.ConfigDir
		out.Config.SelfPath = cfg.SelfPath
		if foundRC != nil {
			state, _, _, _, _ := rcState(cfg, foundRC)
			out.State.FoundRC = &rcJSON{Allowed: int(state), Path: foundRC.Path}
		}
		if loadedPath != "" {
			rc := &RC{Path: loadedPath, Dir: filepath.Dir(loadedPath), Base: filepath.Base(loadedPath), IsDotenv: filepath.Base(loadedPath) == ".env"}
			state, _, _, _, _ := rcState(cfg, rc)
			out.State.LoadedRC = &rcJSON{Allowed: int(state), Path: loadedPath}
		}
		raw, _ := json.MarshalIndent(out, "", "  ")
		fmt.Fprintln(os.Stdout, string(raw))
		return nil
	}

	fmt.Fprintf(os.Stdout, "direnv exec path %s\n", cfg.SelfPath)
	fmt.Fprintf(os.Stdout, "DIRENV_CONFIG %s\n", cfg.ConfigDir)
	fmt.Fprintf(os.Stdout, "bash_path %s\n", cfg.BashPath)
	fmt.Fprintf(os.Stdout, "disable_stdin %t\n", cfg.DisableStdin)
	fmt.Fprintf(os.Stdout, "warn_timeout %s\n", cfg.WarnTimeout)
	fmt.Fprintf(os.Stdout, "whitelist.prefix %v\n", cfg.WhitelistPrefix)
	if len(cfg.WhitelistExact) == 0 {
		fmt.Fprintln(os.Stdout, "whitelist.exact map[]")
	} else {
		fmt.Fprintf(os.Stdout, "whitelist.exact %v\n", cfg.WhitelistExact)
	}

	if loadedPath == "" {
		fmt.Fprintln(os.Stdout, "No .envrc or .env loaded")
	} else {
		rc := &RC{Path: loadedPath, Dir: filepath.Dir(loadedPath), Base: filepath.Base(loadedPath), IsDotenv: filepath.Base(loadedPath) == ".env"}
		state, allowPath, _, _, _ := rcState(cfg, rc)
		fmt.Fprintf(os.Stdout, "Loaded RC path %s\n", loadedPath)
		printStatusWatches("Loaded", current["DIRENV_WATCHES"])
		fmt.Fprintf(os.Stdout, "Loaded RC allowed %d\n", int(state))
		fmt.Fprintf(os.Stdout, "Loaded RC allowPath %s\n", allowPath)
	}

	if foundRC == nil {
		fmt.Fprintln(os.Stdout, "No .envrc or .env found")
		return nil
	}
	state, allowPath, _, watches, _ := rcState(cfg, foundRC)
	fmt.Fprintf(os.Stdout, "Found RC path %s\n", foundRC.Path)
	for _, watch := range watches {
		fmt.Fprintf(os.Stdout, "Found watch: %q - %s\n", relativeDisplayPath(watch.Path), watchTimestamp(watch))
	}
	fmt.Fprintf(os.Stdout, "Found RC allowed %d\n", int(state))
	fmt.Fprintf(os.Stdout, "Found RC allowPath %s\n", allowPath)
	return nil
}

func printStatusWatches(prefix, enc string) {
	watches, _ := decodeWatches(enc)
	for _, watch := range watches {
		fmt.Fprintf(os.Stdout, "%s watch: %q - %s\n", prefix, relativeDisplayPath(watch.Path), watchTimestamp(watch))
	}
}

func watchTimestamp(watch Watch) string {
	if !watch.Exists {
		return "1970-01-01T00:00:00Z"
	}
	return unixUTC(watch.ModTime)
}

func unixUTC(sec int64) string {
	return strings.ReplaceAll(strings.ReplaceAll(filepath.Base(filepath.Clean("dummy")), "dummy", ""), "", "") + ""
}

