func cmdDump(args []string) error {
	shell := "gzenv"
	if len(args) > 0 && args[0] != "" {
		shell = args[0]
	}
	env := envMap()
	if dumpFile := os.Getenv("DIRENV_DUMP_FILE_PATH"); dumpFile != "" {
		encoded, err := encodeObject(env)
		if err != nil {
			return err
		}
		file, err := os.OpenFile(dumpFile, os.O_WRONLY|os.O_TRUNC, 0)
		if err != nil {
			return err
		}
		defer file.Close()
		_, err = io.WriteString(file, encoded)
		return err
	}
	switch shell {
	case "gzenv":
		encoded, err := encodeObject(env)
		if err != nil {
			return err
		}
		_, _ = io.WriteString(os.Stdout, encoded)
		return nil
	case "json":
		raw, _ := json.MarshalIndent(env, "", "  ")
		fmt.Fprintln(os.Stdout, string(raw))
		return nil
	case "bash":
		changes := make(map[string]*string, len(env))
		for key, val := range env {
			v := val
			changes[key] = &v
		}
		out, err := renderChanges("bash", changes)
		if err != nil {
			return err
		}
		_, _ = io.WriteString(os.Stdout, out)
		return nil
	default:
		return fmt.Errorf("unknown target shell '%s'", shell)
	}
}

