func cmdWatch(args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("unknown target shell ''")
	}
	shell := args[0]
	if !supportsExportShell(shell) {
		return fmt.Errorf("unknown target shell '%s'", shell)
	}
	existing, _ := decodeWatches(os.Getenv("DIRENV_WATCHES"))
	incoming := make([]Watch, 0, len(args)-1)
	for _, path := range args[1:] {
		abs, err := filepath.Abs(path)
		if err != nil {
			return err
		}
		incoming = append(incoming, newWatch(abs))
	}
	merged := mergeWatches(existing, incoming)
	enc, err := encodeObject(merged)
	if err != nil {
		return err
	}
	return renderToStdout(shell, map[string]*string{"DIRENV_WATCHES": &enc})
}

func cmdWatchDir(args []string) error {
	if len(args) < 2 {
		return errors.New("invalid arguments")
	}
	shell := args[0]
	if !supportsExportShell(shell) {
		return fmt.Errorf("unknown target shell '%s'", shell)
	}
	root, err := filepath.Abs(args[1])
	if err != nil {
		return err
	}
	existing, _ := decodeWatches(os.Getenv("DIRENV_WATCHES"))
	var incoming []Watch
	err = filepath.Walk(root, func(path string, info os.FileInfo, walkErr error) error {
		if walkErr != nil {
			return nil
		}
		incoming = append(incoming, newWatch(path))
		return nil
	})
	if err != nil {
		return err
	}
	merged := mergeWatches(existing, incoming)
	enc, err := encodeObject(merged)
	if err != nil {
		return err
	}
	return renderToStdout(shell, map[string]*string{"DIRENV_WATCHES": &enc})
}

func cmdWatchList(args []string) error {
	shell := "gzenv"
	if len(args) > 0 {
		shell = args[0]
	}
	var watches []Watch
	data, _ := io.ReadAll(os.Stdin)
	for _, line := range strings.Split(strings.TrimSpace(string(data)), "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		parts := strings.SplitN(line, " ", 2)
		if len(parts) != 2 {
			continue
		}
		watches = append(watches, newWatch(parts[1]))
	}
	enc, err := encodeObject(watches)
	if err != nil {
		return err
	}
	if shell == "gzenv" {
		_, _ = io.WriteString(os.Stdout, enc)
		return nil
	}
	return renderToStdout(shell, map[string]*string{"DIRENV_WATCHES": &enc})
}

