func cmdCheckRequired(cfg Config, args []string) error {
	if len(args) == 0 {
		return errors.New("invalid arguments")
	}
	if args[0] == "approve" {
		if len(args) < 3 {
			return errors.New("invalid arguments")
		}
		envrcPath := args[1]
		envrcDir := filepath.Dir(envrcPath)
		for _, rel := range args[2:] {
			if err := approveRequiredPath(cfg, envrcPath, envrcDir, rel); err != nil {
				return err
			}
		}
		return nil
	}
	shell := args[0]
	if len(args) < 2 {
		return errors.New("invalid arguments")
	}
	if shell != "bash" {
		return fmt.Errorf("unknown target shell '%s'", shell)
	}
	envrcPath := args[1]
	envrcDir := filepath.Dir(envrcPath)
	if len(args) == 2 {
		return nil
	}
	for _, rel := range args[2:] {
		if filepath.IsAbs(rel) {
			fmt.Fprintf(os.Stdout, "log_error %s;\nexit 1;\n", bashQuote("require_allowed: path must be relative: "+rel))
			return nil
		}
	}
	var pending []string
	for _, rel := range args[2:] {
		ok, err := requiredApproved(cfg, envrcPath, envrcDir, rel)
		if err != nil {
			return err
		}
		if !ok {
			pending = append(pending, rel)
		}
	}
	if len(pending) == 0 {
		return nil
	}
	joined := strings.Join(pending, " ")
	msg := pending[0] + " requires approval. Run 'direnv allow' to approve."
	fmt.Fprintf(os.Stdout, "export DIRENV_REQUIRED=%s;log_error %s;\nexit 0;\n", bashQuote(joined), bashQuote(msg))
	return nil
}

func approveRequiredPath(cfg Config, envrcPath, envrcDir, rel string) error {
	abs := filepath.Join(envrcDir, rel)
	data, err := os.ReadFile(abs)
	if err != nil {
		return err
	}
	path := requiredPathFor(envrcPath, rel, data, cfg)
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(envrcPath+"\n"+rel+"\n"), 0o644)
}

func requiredApproved(cfg Config, envrcPath, envrcDir, rel string) (bool, error) {
	abs := filepath.Join(envrcDir, rel)
	data, err := os.ReadFile(abs)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			data = nil
		} else {
			return false, err
		}
	}
	return exists(requiredPathFor(envrcPath, rel, data, cfg)), nil
}

func cmdDotenv(cfg Config, args []string) error {
	shell := "gzenv"
	path := ".env"
	if len(args) > 0 {
		if supportsExportShell(args[0]) {
			shell = args[0]
			if len(args) > 1 {
				path = args[1]
			}
		} else {
			path = args[0]
		}
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return err
	}
	base := envMap()
	evaluated, err := evaluateDotenv(cfg, abs, base)
	if err != nil && len(evaluated.Env) == 0 {
		return err
	}
	target := sanitizeEvaluatedEnv(base, evaluated.Env, false)
	return renderToStdout(shell, changesBetween(base, target))
}

func cmdPrune(cfg Config) error {
	allowDir := filepath.Join(cfg.DataDir, "allow")
	entries, _ := os.ReadDir(allowDir)
	for _, entry := range entries {
		path := filepath.Join(allowDir, entry.Name())
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		rcPath := strings.TrimSpace(string(data))
		content, err := os.ReadFile(rcPath)
		if err != nil || allowPathFor(rcPath, content, cfg) != path {
			_ = os.Remove(path)
		}
	}
	reqRoot := filepath.Join(cfg.DataDir, "allowed-required")
	_ = filepath.Walk(reqRoot, func(path string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return nil
		}
		parts := strings.Split(strings.TrimSpace(string(data)), "\n")
		if len(parts) != 2 {
			_ = os.Remove(path)
			return nil
		}
		envrcPath, rel := parts[0], parts[1]
		abs := filepath.Join(filepath.Dir(envrcPath), rel)
		content, err := os.ReadFile(abs)
		if err != nil || requiredPathFor(envrcPath, rel, content, cfg) != path {
			_ = os.Remove(path)
		}
		return nil
	})
	return nil
}

func supportsExportShell(shell string) bool {
	for _, candidate := range exportShells {
		if shell == candidate {
			return true
		}
	}
	return false
}

func renderToStdout(shell string, changes map[string]*string) error {
	if len(changes) == 0 {
		return nil
	}
	out, err := renderChanges(shell, changes)
	if err != nil {
		return err
	}
	_, _ = io.WriteString(os.Stdout, out)
	return nil
}

func mergedWatchesFromEnv(encoded string, base []Watch) []Watch {
	existing, _ := decodeWatches(encoded)
	return mergeWatches(existing, base)
}

func baseEnvFromCurrent() map[string]string {
	return baseEnvFromMap(envMap())
}

func baseEnvFromMap(current map[string]string) map[string]string {
	base := cloneEnv(current)
	if diff, err := decodeDiff(current["DIRENV_DIFF"]); err == nil {
		base = revertEnv(base, diff)
	}
	delete(base, "DIRENV_DIFF")
	return base
}

