		fmt.Fprintln(os.Stdout, "  Checks if required files have been allowed")
	}
	fmt.Fprintln(os.Stdout, "block [PATH_TO_RC]:")
	fmt.Fprintln(os.Stdout, "  aliases: deny, disallow, revoke")
	fmt.Fprintln(os.Stdout, "  Revokes the authorization of a given .envrc or .env file.")
