func statusLog(cfg Config, message string) {
	if cfg.LogFormat == "-" {
		return
	}
	if cfg.LogFilter != nil && !cfg.LogFilter.MatchString(message) {
		return
	}
	fmt.Fprintf(os.Stderr, "\x1b[0mdirenv: %s\n", message)
}

func fatalErr(err error) {
	fmt.Fprintf(os.Stderr, "\x1b[31mdirenv: error %s\x1b[0m\n", err.Error())
	os.Exit(1)
}

